-- ==============================================================================                                                                                                                         
-- Migration: 003_row_level_security.sql                                                                                                                                                                  
-- Description: Helper functions and Row-Level Security (RLS) policies                                                                                                                                    
-- ==============================================================================                                                                                                                         
                                                                                                                                                                                                              
-- ------------------------------------------------------------------------------                                                                                                                         
-- 1. Helper Security Functions (SECURITY DEFINER avoids recursion loops)                                                                                                                                 
-- ------------------------------------------------------------------------------ 

-- Check if the current logged-in user is an active member of the givern org
    CREATE OR REPLACE FUNCTION public.is_org_member(lookup_org_id UUID)                                                                                                                                       
    RETURNS BOOLEAN                                                                                                                                                                                           
    LANGUAGE sql                                                                                                                                                                                              
    SECURITY DEFINER                                                                                                                                                                                          
    SET search_path = public                                                                                                                                                                                  
    STABLE                                                                                                                                                                                                    
    AS $$                                                                                                                                                                                                     
      SELECT EXISTS (                                                                                                                                                                                         
        SELECT 1                                                                                                                                                                                              
        FROM public.org_memberships                                                                                                                                                                           
        WHERE org_id = lookup_org_id                                                                                                                                                                          
          AND user_id = auth.uid()                                                                                                                                                                            
          AND is_active = true                                                                                                                                                                                
      );                                                                                                                                                                                                      
    $$;                                                                                                                                                                                                       
                                                                                                                                                                                                              
    -- Check if the current logged-in user is an officer/president of the given org                                                                                                                           
    CREATE OR REPLACE FUNCTION public.is_org_admin(lookup_org_id UUID)                                                                                                                                        
    RETURNS BOOLEAN                                                                                                                                                                                           
    LANGUAGE sql                                                                                                                                                                                              
    SECURITY DEFINER                                                                                                                                                                                          
    SET search_path = public                                                                                                                                                                                  
    STABLE                                                                                                                                                                                                    
    AS $$                                                                                                                                                                                                     
      SELECT EXISTS (                                                                                                                                                                                         
        SELECT 1                                                                                                                                                                                              
        FROM public.org_memberships                                                                                                                                                                           
        WHERE org_id = lookup_org_id                                                                                                                                                                          
          AND user_id = auth.uid()                                                                                                                                                                            
          AND is_active = true                                                                                                                                                                                
          AND role IN ('president', 'treasurer', 'officer')                                                                                                                                                   
      );                                                                                                                                                                                                      
    $$;                                                                                                                                                                                                       
                                                                                                                                                                                                              
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- 2. Enable RLS on All Core Tables                                                                                                                                                                       
    -- ------------------------------------------------------------------------------                                                                                                                         
    ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;                                                                                                                                               
    ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;                                                                                                                                                    
    ALTER TABLE public.org_memberships ENABLE ROW LEVEL SECURITY;                                                                                                                                             
                                                                                                                                                                                                              
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- 3. Policies: profiles                                                                                                                                                                                  
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- Any authenticated user can read public profile names/avatars                                                                                                                                           
    CREATE POLICY "Profiles are viewable by authenticated users"                                                                                                                                              
      ON public.profiles                                                                                                                                                                                      
      FOR SELECT                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (true);                                                                                                                                                                                           
                                                                                                                                                                                                              
    -- Users can only update their own profile                                                                                                                                                                
    CREATE POLICY "Users can update their own profile"                                                                                                                                                        
      ON public.profiles                                                                                                                                                                                      
      FOR UPDATE                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (auth.uid() = id)                                                                                                                                                                                 
      WITH CHECK (auth.uid() = id);                                                                                                                                                                           
                                                                                                                                                                                                              
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- 4. Policies: organizations                                                                                                                                                                             
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- Members can view the organizations they belong to                                                                                                                                                      
    CREATE POLICY "Members can view their organizations"                                                                                                                                                      
      ON public.organizations                                                                                                                                                                                 
      FOR SELECT                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (public.is_org_member(id));                                                                                                                                                                       
                                                                                                                                                                                                              
    -- Any authenticated user can create an organization (e.g. during club registration)                                                                                                                      
    CREATE POLICY "Authenticated users can create organizations"                                                                                                                                              
      ON public.organizations                                                                                                                                                                                 
      FOR INSERT                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      WITH CHECK (true);                                                                                                                                                                                      
                                                                                                                                                                                                              
    -- Only org admins/presidents can update organization settings                                                                                                                                            
    CREATE POLICY "Admins can update their organization"                                                                                                                                                      
      ON public.organizations                                                                                                                                                                                 
      FOR UPDATE                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (public.is_org_admin(id))                                                                                                                                                                         
      WITH CHECK (public.is_org_admin(id));                                                                                                                                                                   
                                                                                                                                                                                                              
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- 5. Policies: org_memberships                                                                                                                                                                           
    -- ------------------------------------------------------------------------------                                                                                                                         
    -- Users can view memberships for organizations they belong to                                                                                                                                            
    CREATE POLICY "Members can view roster of their organizations"                                                                                                                                            
      ON public.org_memberships                                                                                                                                                                               
      FOR SELECT                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (public.is_org_member(org_id) OR auth.uid() = user_id);                                                                                                                                           
                                                                                                                                                                                                              
    -- Org admins can manage memberships (promote, demote, update titles)                                                                                                                                     
    CREATE POLICY "Admins can update organization memberships"                                                                                                                                                
      ON public.org_memberships                                                                                                                                                                               
      FOR UPDATE                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (public.is_org_admin(org_id))                                                                                                                                                                     
      WITH CHECK (public.is_org_admin(org_id));                                                                                                                                                               
                                                                                                                                                                                                              
    -- Org admins can remove members                                                                                                                                                                          
    CREATE POLICY "Admins can delete organization memberships"                                                                                                                                                
      ON public.org_memberships                                                                                                                                                                               
      FOR DELETE                                                                                                                                                                                              
      TO authenticated                                                                                                                                                                                        
      USING (public.is_org_admin(org_id));   
